<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Balloon Pop! - Level 1</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap" rel="stylesheet">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #1a1a2e; }
  body { font-family: 'Press Start 2P', monospace; }
  #game { display: block; width: 100vw; height: 100vh; cursor: crosshair; }
  .overlay {
    position: fixed; inset: 0; display: flex; flex-direction: column;
    align-items: center; justify-content: center; gap: 24px;
    background: rgba(10, 10, 30, 0.85); z-index: 10;
  }
  .hidden { display: none !important; }
  h1 { color: #ffd93d; font-size: clamp(20px, 5vw, 48px); text-shadow: 4px 4px 0 #c0392b; text-align: center; line-height: 1.4; }
  h2 { color: #ff6b6b; font-size: clamp(16px, 4vw, 36px); text-shadow: 3px 3px 0 #2c3e50; }
  .sub { color: #ecf0f1; font-size: clamp(8px, 1.6vw, 14px); text-align: center; line-height: 2; }
  .btn {
    font-family: inherit; font-size: clamp(12px, 2.4vw, 20px); color: #fff;
    background: linear-gradient(#f39c12, #d35400); border: 4px solid #fff;
    padding: 16px 32px; cursor: pointer; box-shadow: 0 6px 0 #7e3300;
    transition: transform 0.05s;
  }
  .btn:hover { filter: brightness(1.15); }
  .btn:active { transform: translateY(4px); box-shadow: 0 2px 0 #7e3300; }
  #finalScore { color: #ffd93d; font-size: clamp(14px, 3vw, 28px); }
</style>
</head>
<body>
<canvas id="game"></canvas>

<div id="startScreen" class="overlay">
  <h1>BALLOON POP!</h1>
  <div class="sub">
    HOLD MOUSE TO DRAW THE BOW<br>
    AIM WITH THE CURSOR - RELEASE TO FIRE<br>
    POP 15 BALLOONS TO WIN<br>
    5 MISSES AND YOU LOSE
  </div>
  <button class="btn" id="startBtn">START</button>
</div>

<div id="endScreen" class="overlay hidden">
  <h2 id="endTitle">GAME OVER</h2>
  <div id="finalScore"></div>
  <button class="btn" id="retryBtn">PLAY AGAIN</button>
</div>

